@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def format_stack(stack, level):
        if level <= 0:
            return ""
        return "\n".join(f"  File \"{frame.filename}\", line {frame.lineno}, in {frame.name}" for frame in stack[:level])

    def format_path(path, level):
        if level <= 0:
            return ""
        return "\n".join(f"    {item}" for item in path[:level])

    stack = e.__traceback__
    path = e.args

    return f"{e.__class__.__name__}: {e}\n{format_stack(stack, max_level)}\n{format_path(path, max_path_level)}"

